/**
 * Typed wrappers around the Wails-generated bindings.
 *
 * The generated bindings are plain JavaScript with JSDoc types. This
 * module re-exports them behind a stable, strongly typed surface so the
 * React components never import generated files directly.
 *
 * The generated model types mark every array as nullable. The backend
 * always sends an array, so the normalisers below turn the nullable
 * fields into the arrays the components expect. That normalisation lives
 * here, in the single place the generated types enter the application.
 *
 * The bindings are regenerated by `wails3 generate bindings` and are not
 * checked in.
 */

import * as AppServiceBindings from '../../bindings/github.com/incurl/parchment/internal/bindings/appservice';
import * as BindingsModels from '../../bindings/github.com/incurl/parchment/internal/bindings/models';
import * as FoldModels from '../../bindings/github.com/incurl/parchment/internal/fold/models';
import * as LetterModels from '../../bindings/github.com/incurl/parchment/internal/letters/models';
import * as JobsModels from '../../bindings/github.com/incurl/parchment/internal/jobs/models';
import * as ConsoleModels from '../../bindings/github.com/incurl/parchment/internal/console/models';

export type Vec2 = FoldModels.Vec2;
export type Vec3 = FoldModels.Vec3;
export type Rect = FoldModels.Rect;
export type Transform = FoldModels.Transform;
export type Placement = FoldModels.Placement;
export type Params = FoldModels.Params;
export type Limits = FoldModels.Limits;
export type Hinge = FoldModels.Hinge;
export type Layout = FoldModels.Layout;
export type Crease = FoldModels.Crease;

/** The fold's computed metrics, with its arrays normalised. */
export type Metrics = Omit<FoldModels.Metrics, 'warnings' | 'flap_depth_mm'> & {
  warnings: string[];
  flap_depth_mm: Record<string, number | undefined>;
};

/** A rigid panel of paper, with its texture coordinates normalised. */
export type Panel = Omit<FoldModels.Panel, 'polygon' | 'sheet_polygon' | 'uv'> & {
  polygon: Vec2[];
  sheet_polygon: Vec2[];
  uv: Vec2[];
};

/** The fold's front panel, with its polygons normalised. */
export type FrontPanel = Omit<FoldModels.FrontPanel, 'polygon' | 'world_polygon'> & {
  polygon: Vec2[];
  world_polygon: Vec2[];
};

/** The complete fold description produced by the Go engine. */
export type Scene = Omit<
  FoldModels.Scene,
  'panels' | 'fold_order' | 'creases' | 'front_panel' | 'metrics'
> & {
  panels: Panel[];
  fold_order: string[];
  creases: Crease[];
  front_panel: FrontPanel;
  metrics: Metrics;
};

/** One saved letter draft. */
export type Letter = Omit<LetterModels.Letter, 'fold'> & { fold: Params };

/**
 * The queue types are kept for the template's queue and console panels,
 * which still ship with the repository as reference implementations.
 */
export type Job = JobsModels.Job & {
  status: 'pending' | 'running' | 'completed' | 'failed' | 'cancelled';
  artifact_ids: string[];
  input_artifact_ids: string[];
  params: Record<string, unknown>;
  result: Record<string, unknown>;
};
export type Artifact = JobsModels.Artifact & {
  kind: 'input' | 'output';
  meta: Record<string, unknown>;
};

/** The event emitted when a job changes state. */
export const EVENT_JOB_UPDATED = 'job:updated';

/** The result of writing a PDF. */
export type ExportResult = BindingsModels.ExportResult;

/** The runtime information shown in the footer. */
export type AppInfo = BindingsModels.AppInfo;

/** The settings as the UI sees them. */
export type Settings = BindingsModels.SettingsView;

/** One debug console entry. */
export type ConsoleEntry = ConsoleModels.Entry;

/** The event emitted when a debug console entry is added. */
export const EVENT_CONSOLE_ENTRY = 'console:entry';


/**
 * normaliseScene turns the nullable generated arrays into plain arrays.
 *
 * The generated types say `Vec2[] | null` because Go slices serialise as
 * null when empty. The engine never returns a null polygon, so the
 * normalisation is a type-level correction rather than a fallback.
 */
function normaliseScene(raw: FoldModels.Scene): Scene {
  const scene = raw as unknown as Scene;
  scene.panels = (raw.panels ?? []).map((panel) => ({
    ...panel,
    polygon: panel.polygon ?? [],
    sheet_polygon: panel.sheet_polygon ?? [],
    uv: panel.uv ?? [],
  }));
  scene.fold_order = raw.fold_order ?? [];
  scene.creases = raw.creases ?? [];
  scene.front_panel = {
    ...raw.front_panel,
    polygon: raw.front_panel.polygon ?? [],
    world_polygon: raw.front_panel.world_polygon ?? [],
  };
  scene.metrics.warnings = raw.metrics.warnings ?? [];
  scene.metrics.flap_depth_mm = raw.metrics.flap_depth_mm ?? {};
  return scene;
}

/** Builds the fold scene for the given parameters. */
export async function foldScene(params: Params): Promise<Scene> {
  const raw = await AppServiceBindings.FoldScene(params as never);
  return normaliseScene(raw as unknown as FoldModels.Scene);
}

/** Returns the fold the application starts from. */
export function defaultFoldParams(): Promise<Params> {
  return AppServiceBindings.DefaultFoldParams() as unknown as Promise<Params>;
}

/** Lists the saved drafts, newest first. */
export async function listLetters(): Promise<Letter[]> {
  const raw = await AppServiceBindings.ListLetters();
  return (raw ?? []) as unknown as Letter[];
}

/** Returns one draft. */
export function getLetter(letterId: string): Promise<Letter> {
  return AppServiceBindings.GetLetter(letterId) as unknown as Promise<Letter>;
}

/** Creates or updates a draft. */
export function saveLetter(letter: Letter): Promise<Letter> {
  return AppServiceBindings.SaveLetter(letter as never) as unknown as Promise<Letter>;
}

/** Removes a draft. */
export function deleteLetter(letterId: string): Promise<void> {
  return AppServiceBindings.DeleteLetter(letterId) as Promise<void>;
}

/** Writes the two-page A4 PDF and returns its path. */
export function exportLetterPDF(
  letterId: string,
  showFoldLines: boolean,
): Promise<ExportResult> {
  return AppServiceBindings.ExportLetterPDF(
    letterId,
    showFoldLines,
  ) as unknown as Promise<ExportResult>;
}

/** Returns the application's name, version and data location. */
export function getAppInfo(): Promise<AppInfo> {
  return AppServiceBindings.GetAppInfo() as unknown as Promise<AppInfo>;
}

/** Returns the recorded debug console entries, oldest first. */
export function listConsoleEntries(): Promise<ConsoleEntry[]> {
  return AppServiceBindings.ListConsoleEntries() as unknown as Promise<ConsoleEntry[]>;
}

/** Discards the recorded debug console entries. */
export function clearConsoleEntries(): Promise<void> {
  return AppServiceBindings.ClearConsoleEntries() as Promise<void>;
}

/** Returns the application settings. The API key is never included. */
export function getSettings(): Promise<Settings> {
  return AppServiceBindings.GetSettings() as unknown as Promise<Settings>;
}

/** Stores the interface preferences, including the zoom level. */
export function saveUI(ui: { zoom: number; theme: string }): Promise<void> {
  return AppServiceBindings.SaveUI(ui as never) as unknown as Promise<void>;
}

/** Submits a job to the template's queue. */
export function submitJob(request: {
  title?: string;
  prompt: string;
  params?: Record<string, unknown>;
  input_artifact_ids?: string[];
}): Promise<Job> {
  return AppServiceBindings.SubmitJob(request as never) as unknown as Promise<Job>;
}

/** Cancels a pending or running job. */
export function cancelJob(jobId: string): Promise<void> {
  return AppServiceBindings.CancelJob(jobId) as Promise<void>;
}

/** Removes a finished job from the queue. */
export function deleteJob(jobId: string): Promise<void> {
  return AppServiceBindings.DeleteJob(jobId) as Promise<void>;
}

/** Re-runs a job with the same parameters. */
export function retryJob(jobId: string): Promise<Job> {
  return AppServiceBindings.RetryJob(jobId) as unknown as Promise<Job>;
}

/** Lists the recorded jobs. */
export function listJobs(limit = 50): Promise<Job[]> {
  return AppServiceBindings.ListJobs(limit) as unknown as Promise<Job[]>;
}

/** Lists the stored artifacts. */
export function listArtifacts(jobId = '', limit = 50): Promise<Artifact[]> {
  return AppServiceBindings.ListArtifacts(jobId, limit) as unknown as Promise<Artifact[]>;
}

/** Removes a stored artifact. */
export function deleteArtifact(artifactId: string): Promise<void> {
  return AppServiceBindings.DeleteArtifact(artifactId) as Promise<void>;
}

/** Stores the API credentials. An empty apiKey keeps the stored key. */
export function saveCredentials(apiKey: string, baseUrl: string): Promise<void> {
  return AppServiceBindings.SaveCredentials(apiKey, baseUrl) as Promise<void>;
}

